input.command:
# Categorize all root markdown files by pattern
ls -1 *.md 2>/dev/null | sort | awk '
BEGIN { 
    session=0; phase=0; task=0; deploy=0; project=0; compound=0; other=0; keep=0
}
/^SESSION_/ { session++; next }
/^PHASE_/ { phase++; next }
/^TASK_/ { task++; next }
/^DEPLOY|^TUNNEL|^ROLLBACK|^FAILURE_RECOVERY/ { deploy++; next }
/^PROJECT_|^COMPREHENSIVE_PROJECT/ { project++; next }
/^COMPOUND_/ { compound++; next }
/^(CLAUDE|README|CONTRIBUTING|CREDITS|CHANGELOG|LICENSE)\.md$/ { keep++; next }
{ other++ }
END {
    printf "Keep (essential):   %3d\n", keep
    printf "SESSION_* files:    %3d\n", session
    printf "PHASE_* files:      %3d\n", phase
    printf "TASK_* files:       %3d\n", task
    printf "Deploy/ops files:   %3d\n", deploy
    printf "Project status:     %3d\n", project
    printf "Compound eng docs:  %3d\n", compound
    printf "Other:              %3d\n", other
    printf "TOTAL:              %3d\n", keep+session+phase+task+deploy+project+compound+other
}'
